(() => {
 const data=window.SCHOOL_DATA;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const facts=j=>[j.term,j.band,j.course].filter(Boolean).join(' · ');
 const links=j=>[...j.lessons.map(id=>data.lessons.find(l=>l.id===id)).filter(Boolean).map(l=>`<a class="text-link" href="lessons.html?lesson=${esc(l.id)}">同主題教案：${esc(l.title)}（${esc(l.band)}）&nbsp;→</a>`),...j.resources.map(id=>data.resources.find(r=>r.id===id)).filter(Boolean).map(r=>`<a class="text-link" href="resource.html?id=${esc(r.id)}">${esc(r.title)}&nbsp;→</a>`)].join('');
 // 沒有適合公開的照片時，改放那一步的題目或原話
 const picture=(j,s,i)=>{const a=data.assets[s.photo];return a?`<button class="photo-open${s.fit==='contain'?' is-document':''}" type="button" data-photo="${esc(s.photo)}" data-caption="${esc(j.short)}｜第${i+1}步 ${esc(s.title)}" aria-label="放大第${i+1}步的照片：${esc(s.title)}"><img src="${esc(a.thumb)}" alt="${esc(s.alt)}" loading="lazy" decoding="async"${s.pos?` style="object-position:${esc(s.pos)}"`:''}><span>放大觀看 ↗</span></button>`:`<div class="journey-paper"><p>${esc(s.paper)}</p></div>`;};
 const step=(j,s,i)=>`<li class="journey-step"><p class="journey-step-no"><b>${i+1}</b><span>/ ${j.steps.length}</span></p>${picture(j,s,i)}<h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></li>`;
 window.showJourneys=()=>{
  const main=document.getElementById('main'),list=data.journeys||[];
  main.innerHTML=`<header class="page-heading"><div class="breadcrumb"><a href="index.html">首頁</a><span>/</span><a href="learning.html">課程與教材</a><span>/</span><span>我們怎麼學</span></div><p class="eyebrow">113–114學年度 · ${list.length}堂課的學習足跡</p><h1>一步一步，看見我們怎麼學。</h1><p>畫草圖、配顏色，卡關了就重來；也向部落耆老和返鄉青年請教。從開始到完成，每一步都在這裡。</p></header><div class="page-body journey-page"><nav class="topic-nav" aria-label="課程步驟卡">${list.map((j,n)=>`<a href="#${esc(j.id)}">${String(n+1).padStart(2,'0')} ${esc(j.short)}</a>`).join('')}</nav><p class="journey-note">照片裡的名字和臉都打上了馬賽克。點照片可以放大<span class="journey-swipe">，左右滑動看下一步</span>。</p><div class="journey-list">${list.map((j,n)=>`<article class="journey steps-${j.steps.length}" id="${esc(j.id)}" style="--steps:${j.steps.length}"><div class="journey-head"><p class="eyebrow">${String(n+1).padStart(2,'0')} / ${esc(facts(j))}</p><h2>${esc(j.title)}</h2><p>${esc(j.lead)}</p></div><ol class="journey-steps" aria-label="${esc(j.short)}的學習步驟">${j.steps.map((s,i)=>step(j,s,i)).join('')}</ol>${j.voices?.length?`<div class="journey-voices">${j.voices.map(v=>`<blockquote><p>「${esc(v.text)}」</p><footer>${esc(v.about)}</footer></blockquote>`).join('')}</div>`:''}${links(j)?`<div class="journey-links">${links(j)}</div>`:''}</article>`).join('')}</div><section class="journey-next"><h2>作品完成了，還能去哪裡看？</h2><p>成果展、比賽和舞台上，也有這些課的作品；教案書屋可以看到老師怎麼設計每一堂課。</p><div class="detail-actions"><a class="button primary" href="stories.html">看活動與成果 →</a><a class="button" href="lessons.html">按主題找教案 →</a></div></section></div>`;
 };
})();
